CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, role VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tickets (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, category VARCHAR(40) NOT NULL, priority VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, reporter_id BIGINT NOT NULL, technician_id BIGINT NULL, resolution_notes TEXT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT fk_ticket_reporter FOREIGN KEY (reporter_id) REFERENCES users(id), CONSTRAINT fk_ticket_technician FOREIGN KEY (technician_id) REFERENCES users(id));
CREATE TABLE assets (id BIGINT AUTO_INCREMENT PRIMARY KEY, asset_tag VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, category VARCHAR(50) NOT NULL, manufacturer VARCHAR(100), serial_number VARCHAR(100), assigned_user_id BIGINT NULL, status VARCHAR(30) NOT NULL, purchase_date DATE, notes TEXT, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT fk_asset_user FOREIGN KEY (assigned_user_id) REFERENCES users(id));
CREATE TABLE ticket_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, ticket_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, action VARCHAR(120) NOT NULL, details VARCHAR(500), created_at TIMESTAMP NOT NULL, CONSTRAINT fk_history_ticket FOREIGN KEY (ticket_id) REFERENCES tickets(id), CONSTRAINT fk_history_actor FOREIGN KEY (actor_id) REFERENCES users(id));
CREATE INDEX idx_ticket_status ON tickets(status); CREATE INDEX idx_ticket_priority ON tickets(priority); CREATE INDEX idx_asset_status ON assets(status);
